# tools/executor.py
"""Tool executor abstraction for localized modification."""

import importlib
import inspect
from typing import Dict, Any, Tuple, Optional
from tools.base import BaseTool


class ToolExecutionResult:
    """Result wrapper for consistent tool execution output."""

    def __init__(self, success: bool, data: Any = None, error: Optional[str] = None):
        self.success = success
        self.data = data
        self.error = error

    def to_dict(self) -> Dict[str, Any]:
        """Convert result to dictionary."""
        result = {"success": self.success}
        if self.data is not None:
            result["data"] = self.data
        if self.error is not None:
            result["error"] = self.error
        return result


class ToolExecutor:
    """Handles dynamic tool loading, instantiation, and execution."""

    def __init__(self, tools_module_path: str = "tools"):
        """Initialize executor with tools module path.

        Args:
            tools_module_path: Base module path for tools (default: "tools")
        """
        self.tools_module_path = tools_module_path
        self._instance_cache: Dict[str, BaseTool] = {}

    def execute(self, tool_name: str, input_data: Dict[str, Any]) -> ToolExecutionResult:
        """Dynamically load and execute a tool.

        Args:
            tool_name: Name of the tool to execute
            input_data: Input parameters for the tool

        Returns:
            ToolExecutionResult with success status and data/error
        """
        try:
            # Check cache first
            if tool_name in self._instance_cache:
                tool_instance = self._instance_cache[tool_name]
            else:
                # Import module dynamically
                module = importlib.import_module(f"{self.tools_module_path}.{tool_name}")

                # Find and instantiate tool class
                tool_instance = self._find_tool_instance(module, tool_name)
                if tool_instance is None:
                    return ToolExecutionResult(False, error=f"Tool class not found for: {tool_name}")

                # Cache instance for future use
                self._instance_cache[tool_name] = tool_instance

            # Execute tool with provided input
            result = tool_instance.execute(**input_data)
            return ToolExecutionResult(True, data=result)

        except ImportError as e:
            return ToolExecutionResult(False, error=f"Failed to import tool '{tool_name}': {str(e)}")
        except Exception as e:
            return ToolExecutionResult(False, error=f"Error executing tool '{tool_name}': {str(e)}")

    def _find_tool_instance(self, module, tool_name: str) -> Optional[BaseTool]:
        """Find and instantiate a tool class matching the given name.

        Args:
            module: The module to search
            tool_name: Expected tool name

        Returns:
            Instance of the matching tool class or None
        """
        for name, obj in inspect.getmembers(module):
            if inspect.isclass(obj) and issubclass(obj, BaseTool) and obj != BaseTool:
                try:
                    tool_instance = obj()
                    if tool_instance.name == tool_name:
                        return tool_instance
                except Exception:
                    # Skip tools that fail to instantiate
                    continue
        return None

    def clear_cache(self):
        """Clear the tool instance cache."""
        self._instance_cache.clear()

    def get_cached_tool_names(self) -> list:
        """Get list of tool names currently cached."""
        return list(self._instance_cache.keys())
